(function(root){
'use strict';
const data=root.qmLocaleData,fx=data.fx;
const supported=['en','zh-CN','es','fr','de','ja','ko','id'];
const euroCountries='AT BE CY DE EE ES FI FR GR HR IE IT LT LU LV MT NL PT SI SK'.split(' ');
const currencies={US:'USD',CN:'CNY',HK:'HKD',TW:'USD',MO:'HKD',JP:'JPY',KR:'KRW',ID:'IDR',SG:'SGD',GB:'GBP',CA:'CAD',AU:'AUD',NZ:'NZD',CH:'CHF',MY:'MYR',TH:'THB',PH:'PHP',IN:'INR',MX:'MXN',BR:'BRL',ZA:'ZAR',SE:'SEK',NO:'NOK',DK:'DKK',PL:'PLN'};
function browserLanguage(values){for(const value of values||[]){const short=String(value).split('-')[0].toLowerCase();if(short==='zh')return 'zh-CN';if(supported.includes(short))return short}return 'en'}
function forCountry(country,languages=[]){const code=String(country||'').toUpperCase(),browser=browserLanguage(languages);let language='en';if(['CN','HK','TW','MO'].includes(code))language='zh-CN';else if(code==='JP')language='ja';else if(code==='KR')language='ko';else if(code==='ID')language='id';else if(['DE','AT'].includes(code))language='de';else if(['FR','MC'].includes(code))language='fr';else if(['ES','MX','AR','CL','CO','PE','EC','VE','UY','BO','PY','CR','PA','GT','HN','SV','NI','DO'].includes(code))language='es';else if(code==='CA')language=browser==='fr'?'fr':'en';else if(['CH','BE','LU'].includes(code))language=['de','fr'].includes(browser)?browser:'fr';const currency=euroCountries.includes(code)?'EUR':currencies[code]||'USD';return {language,currency,country:code}}
function readPrefs(){try{const p=JSON.parse(localStorage.getItem('qm-preferences-v1')||'{}');return {language:supported.includes(p.language)?p.language:null,currency:Object.hasOwn(fx.rates,p.currency)?p.currency:null,manualLanguage:p.manualLanguage===true,manualCurrency:p.manualCurrency===true}}catch{return {}}}
function savePrefs(p){try{localStorage.setItem('qm-preferences-v1',JSON.stringify(p))}catch{}}
function amounts(currency){const code=Object.hasOwn(fx.rates,currency)?currency:'USD';const digits=['JPY','KRW','IDR'].includes(code)?0:2,scale=10**digits,rate=fx.rates[code]/fx.rates.USD;const rental=Math.round(499*rate*scale),annual=Math.round(1999*rate*scale);return {code,digits,499:rental/scale,1999:annual/scale,2498:(rental+annual)/scale}}
function format(usd,currency,language){const value=amounts(currency);return new Intl.NumberFormat(language,{style:'currency',currency:value.code,currencyDisplay:'code',minimumFractionDigits:value.digits,maximumFractionDigits:value.digits}).format(value[usd])}
let currentCurrency=readPrefs().currency||fx.currencyByLanguage[document.documentElement.lang]||'USD';
function escapeRegex(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/[\s\u00a0\u202f]+/g,'[\\s\\u00a0\\u202f]+')}
const tokens=new Map();for(const [lang,currency] of Object.entries(fx.currencyByLanguage)){for(const usd of [499,1999,2498])tokens.set(format(usd,currency,lang),usd)}for(const usd of [499,1999,2498]){const n=usd.toLocaleString('en-US');for(const token of ['$'+n,'$'+n+'.00','$'+n+'.00 USD',n+' USD',n+' 美元'])tokens.set(token,usd)}
const variants=[...tokens].sort((a,b)=>b[0].length-a[0].length),moneyPattern=new RegExp(variants.map(([s])=>'('+escapeRegex(s)+')').join('|'),'g');
function markAmounts(container){if(!container||!document.createTreeWalker)return;const walker=document.createTreeWalker(container,NodeFilter.SHOW_TEXT,{acceptNode(node){if(!node.parentElement||node.parentElement.closest('script,style,textarea,input,select,[data-money-usd],.payment-summary,[data-paypal-hosted],.source-reference'))return NodeFilter.FILTER_REJECT;return /\d/.test(node.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}}),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){moneyPattern.lastIndex=0;const matches=[...node.nodeValue.matchAll(moneyPattern)];if(!matches.length)continue;const fragment=document.createDocumentFragment();let start=0;for(const match of matches){fragment.append(document.createTextNode(node.nodeValue.slice(start,match.index)));const index=match.slice(1).findIndex(v=>v!==undefined),usd=variants[index][1],span=document.createElement('span');span.dataset.moneyUsd=String(usd);span.textContent=format(usd,currentCurrency,document.documentElement.lang);fragment.append(span);start=match.index+match[0].length}fragment.append(document.createTextNode(node.nodeValue.slice(start)));node.replaceWith(fragment)}}
function refresh(){const main=document.querySelector('#app');if(main){let note=main.querySelector('[data-currency-note]');if(!note){note=document.createElement('p');note.dataset.currencyNote='';note.className='container fine currency-note';main.appendChild(note)}const messages={en:'Indicative local prices · ECB '+fx.date+' · PayPal settlement: USD', 'zh-CN':'当地货币为参考显示 · ECB '+fx.date+' · PayPal 实际结算：USD',es:'Precios locales orientativos · BCE '+fx.date+' · Pago PayPal: USD',fr:'Prix locaux indicatifs · BCE '+fx.date+' · Paiement PayPal : USD',de:'Lokale Richtpreise · EZB '+fx.date+' · PayPal-Abrechnung: USD',ja:'現地通貨は目安 · ECB '+fx.date+' · PayPal 決済：USD',ko:'현지 금액은 참고용 · ECB '+fx.date+' · PayPal 결제: USD',id:'Harga lokal perkiraan · ECB '+fx.date+' · Pembayaran PayPal: USD'};note.textContent=messages[document.documentElement.lang]||messages.en}markAmounts(document.querySelector('#app'));markAmounts(document.querySelector('#modal-body'));document.querySelectorAll('[data-money-usd]').forEach(span=>span.textContent=format(Number(span.dataset.moneyUsd),currentCurrency,document.documentElement.lang));document.querySelectorAll('[data-currency-select]').forEach(select=>select.value=currentCurrency)}
async function detect(){try{const cached=JSON.parse(sessionStorage.getItem('qm-geo-country')||'null');if(cached&&cached.expires>Date.now()&&/^[A-Z]{2}$/.test(cached.country))return cached.country}catch{}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),3000);try{const response=await fetch('https://ipapi.co/json/',{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'});if(!response.ok)throw new Error('Geo unavailable');const result=await response.json(),country=String(result.country_code||'').toUpperCase();if(result.error||!/^[A-Z]{2}$/.test(country))throw new Error('Country unavailable');try{sessionStorage.setItem('qm-geo-country',JSON.stringify({country,expires:Date.now()+86400000}))}catch{}return country}finally{clearTimeout(timer)}}
async function initialize(){refresh();if(/bot|crawler|spider|lighthouse|chatgpt-user|claude-user/i.test(navigator.userAgent||''))return;let interacted=false;const interaction=()=>{interacted=true};document.addEventListener('input',interaction,{once:true});document.addEventListener('pointerdown',interaction,{once:true});const prefs=readPrefs(),route=languageRoute();let choice;try{choice=forCountry(await detect(),navigator.languages)}catch{choice={language:browserLanguage(navigator.languages),currency:fx.currencyByLanguage[route.current]||'USD'}}const latest=readPrefs();if(!latest.manualCurrency){currentCurrency=choice.currency;savePrefs({...latest,currency:currentCurrency});refresh()}const preferred=latest.manualLanguage?latest.language:choice.language;const localizedPath=route.current!=='en';if(!interacted&&!localizedPath&&supported.includes(preferred)&&preferred!==route.current&&location.pathname.indexOf('/pages/commerce-design')!==0&&location.pathname.indexOf('/pages/design-review')!==0&&location.pathname.indexOf('/pages/seo-geo-review')!==0){location.replace((preferred==='en'?'':'/'+preferred)+route.base+location.search+location.hash)}}
document.addEventListener('change',e=>{if(!e.target.matches('[data-currency-select]'))return;if(!Object.hasOwn(fx.rates,e.target.value))return;currentCurrency=e.target.value;savePrefs({...readPrefs(),currency:currentCurrency,manualCurrency:true});refresh()});
root.QuickMindLocale={forCountry,browserLanguage,amounts,format,refresh,initialize,detect};document.addEventListener('DOMContentLoaded',initialize);
})(globalThis);
